# Enterprise Hybrid Retrieval with Reciprocal Rank Fusion (RRF) & Reranking
from rank_bm25 import BM25Okapi
from sentence_transformers import CrossEncoder

def rrf(dense_ranks: dict[str, int], bm25_ranks: dict[str, int], k: int = 60) -> list[tuple[str, float]]:
    scores = {}
    all_docs = set(dense_ranks.keys()) | set(bm25_ranks.keys())
    for doc_id in all_docs:
        score = 0.0
        if doc_id in dense_ranks:
            score += 1.0 / (k + dense_ranks[doc_id])
        if doc_id in bm25_ranks:
            score += 1.0 / (k + bm25_ranks[doc_id])
        scores[doc_id] = score
    return sorted(scores.items(), key=lambda x: x[1], reverse=True)

# Step 2: Cross-encoder reranking on candidate pool
reranker = CrossEncoder("BAAI/bge-reranker-large")
def rerank_top_k(query: str, candidates: list[dict], top_n: int = 5) -> list[dict]:
    pairs = [[query, c["text"]] for c in candidates]
    scores = reranker.predict(pairs)
    ranked = sorted(zip(candidates, scores), key=lambda x: x[1], reverse=True)
    return [doc for doc, _ in ranked[:top_n]]

# Bounded Agentic RAG State Graph with Deterministic Fences
from typing import TypedDict
from langgraph.graph import StateGraph, END

class AgentState(TypedDict):
    query: str
    sub_queries: list[str]
    retrieved_chunks: list[dict]
    iteration: int
    final_answer: str

def plan_node(state: AgentState):
    return {"sub_queries": decompose_query(state["query"]), "iteration": state["iteration"] + 1}

def retrieve_node(state: AgentState):
    chunks = []
    for sq in state["sub_queries"]:
        chunks.extend(hybrid_retrieve(sq, top_k=3))
    return {"retrieved_chunks": deduplicate_and_trim_rbac(chunks)}

def evaluate_gate(state: AgentState):
    if state["iteration"] >= 3:
        return "synthesize"  # Deterministic loop fence
    return "synthesize" if evaluate_groundedness(state) > 0.85 else "refine"

workflow = StateGraph(AgentState)
workflow.add_node("plan", plan_node)
workflow.add_node("retrieve", retrieve_node)
workflow.add_conditional_edges("retrieve", evaluate_gate, {"refine": "plan", "synthesize": "synthesize"})
